function groupNames(r: Rng, cities: string[], n: number): string[] {
  const pats = [
    (c: string, k: number) => `נהגים ${c} ${k}`,
    (c: string, k: number) => `מוניות ${c} ${k}`,
    (c: string) => `הסעות ${c} – בוקר`,
    (c: string) => `הסעות ${c} – ערב`,
    (c: string) => `מוניות ${c} VIP`,
    (c: string) => `נסיעות ${c} ⇄ נתב״ג`,
    (c: string, k: number) => `טרמפים ${c} ${k}`,
    (c: string) => `סדרנים ${c}`,
    (c: string, k: number) => `מיניבוסים ${c} ${k}`,
    (c: string) => `נהגי ${c} – לילה`,
    (c: string, k: number) => `נהגים עצמאיים ${c} ${k}`,
    (c: string, k: number) => `קבוצת ${c} ${k} 🚕`,
    (c: string, k: number) => `הובלות ונסיעות ${c} ${k}`,
    (c: string) => `משמרת בוקר ${c}`,
    (c: string, k: number) => `לוח נסיעות ${c} ${k}`,
  ];
  const out = new Set<string>();
  let guard = 0;
  while (out.size < n && guard++ < n * 50) out.add(r.pick(pats)(r.pick(cities), r.int(1, 24)));
  return [...out];
}

function logoSvg(bg: string, fg: string, text: string, sub: string) {
  return svgData(
    `<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160" viewBox="0 0 160 160"><rect width="160" height="160" rx="36" fill="${bg}"/>` +
      `<rect x="44" y="28" width="72" height="22" rx="6" fill="${fg}"/><text x="80" y="44" font-family="Arial" font-size="14" font-weight="700" text-anchor="middle" fill="${bg}">TAXI</text>` +
      `<text x="80" y="104" font-family="Arial" font-size="40" font-weight="800" text-anchor="middle" fill="${fg}">${text}</text>` +
      `<text x="80" y="132" font-family="Arial" font-size="15" font-weight="600" text-anchor="middle" fill="${fg}" opacity=".85">${sub}</text></svg>`,
  );
}
function proofSvg(amount: number, who: string) {
  return svgData(
    `<svg xmlns="http://www.w3.org/2000/svg" width="360" height="520" viewBox="0 0 360 520"><rect width="360" height="520" fill="#f4f6fb"/>` +
      `<rect x="20" y="20" width="320" height="480" rx="24" fill="#fff" stroke="#dde1e6"/><circle cx="180" cy="110" r="44" fill="#21c59a"/>` +
      `<path d="M160 110l14 14 28-30" stroke="#fff" stroke-width="9" fill="none" stroke-linecap="round" stroke-linejoin="round"/>` +
      `<text x="180" y="200" font-family="Arial" font-size="22" font-weight="700" text-anchor="middle" fill="#161a21">ההעברה בוצעה</text>` +
      `<text x="180" y="262" font-family="Arial" font-size="44" font-weight="800" text-anchor="middle" fill="#161a21">₪${amount}</text>` +
      `<text x="180" y="312" font-family="Arial" font-size="16" text-anchor="middle" fill="#677282">אל: BotiX – מאיר</text>` +
      `<text x="180" y="340" font-family="Arial" font-size="16" text-anchor="middle" fill="#677282">מאת: ${who}</text>` +
      `<text x="180" y="400" font-family="Arial" font-size="14" text-anchor="middle" fill="#8e98a6">אסמכתה 48213977 · bit</text></svg>`,
  );
}

