  // ---------------- people ----------------
  const prof = (o: Row) => add('profiles', { title: null, is_primary: false, is_active: true, created_at: ago(300 * DAY), station_id: ID.home, ...o });
  prof({ id: ID.meir, email: 'meir@botix.co.il', full_name: 'מאיר', role: 'owner', is_primary: true, title: 'בעל המערכת', created_at: ago(400 * DAY) });
  prof({ id: ID.ronit, email: 'ronit@botix.co.il', full_name: 'רונית שלום', role: 'admin', created_at: ago(200 * DAY) });
